-- Where the full search of /api/search spends its time (B32, after 0.80.24), read only: the main statement of
-- each type as the API plans it (store.query(indexes_only=True): no sequential scan), under EXPLAIN (ANALYZE,
-- BUFFERS). Made with the code of this release on lawgraph_small: the constants of its rank (N, df, mean
-- lengths) are of that database; the plan shape and the rows and pages read are what counts.
-- 1-2: the votes of "BW" as 0.80.24 searches them (LIKE '%bw%': no trigram, every vote rechecked) and as this
-- release does (the start of a word: the trigrams of "  b" and " bw"); 3-5: the articles, dossiers and
-- judgments of "Wetboek van Strafrecht" (cold 1.9-2.6 s, warm 0.3 s on 29 Oct): run twice, the first is
-- cold, "shared read" of the second shows how much stays in the cache.
SET default_transaction_read_only = on;
SET statement_timeout = '30s';
SET enable_seqscan = off;
-- I/O Timings in each plan (a superuser only): a "shared read" from disk takes ms, one from the cache of the OS µs
SELECT set_config('track_io_timing', 'on', false) FROM pg_roles WHERE rolname = current_user AND rolsuper;
\pset pager off

-- 1. 0.80.24: decisions 'BW'
EXPLAIN (ANALYZE, BUFFERS)
WITH recent AS MATERIALIZED ( SELECT r.id, r.date, r.key FROM ( SELECT id, date, key, props FROM decisions ORDER BY date DESC NULLS LAST, key LIMIT 2000 ) r WHERE (lower(coalesce(r.props ->> 'subject', '') || ' ' || coalesce(r.props ->> 'kind', '')) LIKE '%' || lg_like('bw') || '%' OR (char_length((lg_tokens('bw'))[1]) >= 4 AND lower(coalesce(r.props ->> 'subject', '') || ' ' || coalesce(r.props ->> 'kind', '')) LIKE '%' || lg_like((lg_tokens('bw'))[1]) || '%')) ORDER BY r.date DESC NULLS LAST, r.key LIMIT 6 ), found AS MATERIALIZED ( SELECT r.id, r.date, r.key FROM decisions r WHERE (SELECT count(*) FROM recent) < 6 AND (lower(coalesce(r.props ->> 'subject', '') || ' ' || coalesce(r.props ->> 'kind', '')) LIKE '%' || lg_like('bw') || '%' OR (char_length((lg_tokens('bw'))[1]) >= 4 AND lower(coalesce(r.props ->> 'subject', '') || ' ' || coalesce(r.props ->> 'kind', '')) LIKE '%' || lg_like((lg_tokens('bw'))[1]) || '%')) ) SELECT json_build_object( 'id', r.id, 'key', r.key, 'collection', 'decisions', 'type', r.type, 'display_name', r.props -> 'display_name', 'snippet', r.props -> 'subject', 'extra', json_build_object( 'date', r.props -> 'date', 'kind', r.props -> 'kind', 'passed', r.props -> 'passed', 'chamber', r.props -> 'chamber', 'dossier_numbers', r.props -> 'dossier_numbers' ) ) FROM ( SELECT * FROM recent UNION SELECT * FROM found ORDER BY date DESC NULLS LAST, key LIMIT 6 ) top JOIN decisions r ON r.id = top.id ORDER BY r.date DESC NULLS LAST, r.key;

-- 2. this release: decisions 'BW'
EXPLAIN (ANALYZE, BUFFERS)
WITH recent AS MATERIALIZED ( SELECT r.id, r.date, r.key FROM ( SELECT id, date, key, props FROM decisions ORDER BY date DESC NULLS LAST, key LIMIT 2000 ) r WHERE (lower(coalesce(r.props ->> 'subject', '') || ' ' || coalesce(r.props ->> 'kind', '')) LIKE lg_like('bw') || '%' OR lower(coalesce(r.props ->> 'subject', '') || ' ' || coalesce(r.props ->> 'kind', '')) LIKE '% ' || lg_like('bw') || '%' OR lower(coalesce(r.props ->> 'subject', '') || ' ' || coalesce(r.props ->> 'kind', '')) LIKE '%(' || lg_like('bw') || '%' OR (char_length((lg_tokens('bw'))[1]) >= 4 AND lower(coalesce(r.props ->> 'subject', '') || ' ' || coalesce(r.props ->> 'kind', '')) LIKE '%' || lg_like((lg_tokens('bw'))[1]) || '%')) ORDER BY r.date DESC NULLS LAST, r.key LIMIT 6 ), found AS MATERIALIZED ( SELECT r.id, r.date, r.key FROM decisions r WHERE (SELECT count(*) FROM recent) < 6 AND (lower(coalesce(r.props ->> 'subject', '') || ' ' || coalesce(r.props ->> 'kind', '')) LIKE lg_like('bw') || '%' OR lower(coalesce(r.props ->> 'subject', '') || ' ' || coalesce(r.props ->> 'kind', '')) LIKE '% ' || lg_like('bw') || '%' OR lower(coalesce(r.props ->> 'subject', '') || ' ' || coalesce(r.props ->> 'kind', '')) LIKE '%(' || lg_like('bw') || '%' OR (char_length((lg_tokens('bw'))[1]) >= 4 AND lower(coalesce(r.props ->> 'subject', '') || ' ' || coalesce(r.props ->> 'kind', '')) LIKE '%' || lg_like((lg_tokens('bw'))[1]) || '%')) ) SELECT json_build_object( 'id', r.id, 'key', r.key, 'collection', 'decisions', 'type', r.type, 'display_name', r.props -> 'display_name', 'snippet', r.props -> 'subject', 'extra', json_build_object( 'date', r.props -> 'date', 'kind', r.props -> 'kind', 'passed', r.props -> 'passed', 'chamber', r.props -> 'chamber', 'dossier_numbers', r.props -> 'dossier_numbers' ) ) FROM ( SELECT * FROM recent UNION SELECT * FROM found ORDER BY date DESC NULLS LAST, key LIMIT 6 ) top JOIN decisions r ON r.id = top.id ORDER BY r.date DESC NULLS LAST, r.key;

-- 3a. articles 'wetboek van strafrecht', first
EXPLAIN (ANALYZE, BUFFERS)
SELECT json_build_object( 'id', r.id, 'key', r.key, 'collection', 'articles', 'type', r.type, 'display_name', r.props -> 'display_name', 'snippet', left(coalesce(r.props ->> 'text', ''), 200), 'extra', json_build_object( 'bwb_id', r.props -> 'bwb_id', 'celex', r.props -> 'celex', 'article_number', r.props -> 'article_number', 'heading', r.props -> 'heading', 'division_titles', ( SELECT coalesce(json_agg(b -> 'title' ORDER BY n), '[]'::json) FROM json_array_elements(CASE WHEN json_typeof(r.props -> 'breadcrumb') = 'array' THEN r.props -> 'breadcrumb' ELSE '[]'::json END) WITH ORDINALITY AS c(b, n) WHERE coalesce(json_typeof(b -> 'title'), 'null') <> 'null' ), 'instrument_title', (CASE WHEN coalesce(json_typeof(coalesce(by_bwb.props, by_celex.props) -> 'citation_title'), 'null') <> 'null' THEN coalesce(by_bwb.props, by_celex.props) -> 'citation_title' WHEN coalesce(json_typeof(coalesce(by_bwb.props, by_celex.props) -> 'title'), 'null') <> 'null' THEN coalesce(by_bwb.props, by_celex.props) -> 'title' END), 'citation_title', coalesce(by_bwb.props, by_celex.props) -> 'citation_title', 'short_title', coalesce(by_bwb.props, by_celex.props) -> 'short_title', 'instrument_abbreviation', r.props -> 'instrument_abbreviation', 'expired_on', least( lg_str(coalesce(by_bwb.props, by_celex.props) -> 'date_expired'), (CASE WHEN r.bwb_id IS NULL THEN NULL WHEN r.stam_id IS NOT NULL THEN ( SELECT v.valid_until FROM article_versions v WHERE v.bwb_id = r.bwb_id AND v.stam_id = r.stam_id ORDER BY v.valid_from DESC NULLS LAST, v.key DESC LIMIT 1 ) ELSE ( SELECT v.valid_until FROM article_versions v WHERE v.bwb_id = r.bwb_id AND v.article_number = r.article_number ORDER BY v.valid_from DESC NULLS LAST, v.key DESC LIMIT 1 ) END) ) ) ) FROM ( SELECT r.id, (CASE WHEN (r.s_display_name_g LIKE lg_like(lg_fold('wetboek strafrecht')) || '%' OR r.s_display_name_g LIKE '%' || chr(31) || lg_like(lg_fold('wetboek strafrecht')) || '%') OR (r.s_heading_g LIKE lg_like(lg_fold('wetboek strafrecht')) || '%' OR r.s_heading_g LIKE '%' || chr(31) || lg_like(lg_fold('wetboek strafrecht')) || '%') THEN 2 WHEN (f.t7 > 0) AND (f.t18 > 0 OR f.t22 > 0) THEN 1 ELSE 0 END) AS tier, ((CASE WHEN f.t0 > 0 THEN 2.0954469782626255 * f.t0 / (f.t0 + 0.3 + 0.15064675338972164 * f.l0) ELSE 0 END + CASE WHEN f.t2 > 0 THEN 2.09544700392961 * f.t2 / (f.t2 + 0.3 + 0.003080516176958878 * f.l2) ELSE 0 END + CASE WHEN f.t7 > 0 THEN 18.011473079960783 * f.t7 / (f.t7 + 0.3 + 0.09741189844638119 * f.l7) ELSE 0 END + CASE WHEN f.t8 > 0 THEN 8.534757105030126 * f.t8 / (f.t8 + 0.3 + 0.005653691726213725 * f.l8) ELSE 0 END + CASE WHEN f.t15 > 0 THEN 10.624706318033402 * f.t15 / (f.t15 + 0.3 + 0.15064675338972164 * f.l0) ELSE 0 END + CASE WHEN f.t17 > 0 THEN 10.624706614216857 * f.t17 / (f.t17 + 0.3 + 0.003080516176958878 * f.l2) ELSE 0 END + CASE WHEN f.t18 > 0 THEN 67.14616047648563 * f.t18 / (f.t18 + 0.3 + 0.1943145869947276 * f.l3) ELSE 0 END + CASE WHEN f.t21 > 0 THEN 67.14616030122873 * f.t21 / (f.t21 + 0.3 + 0.0027465505099246194 * f.l6) ELSE 0 END + CASE WHEN f.t22 > 0 THEN 26.00914772628777 * f.t22 / (f.t22 + 0.3 + 0.09741189844638119 * f.l7) ELSE 0 END + CASE WHEN f.t23 > 0 THEN 11.033628563627548 * f.t23 / (f.t23 + 0.3 + 0.005653691726213725 * f.l8) ELSE 0 END) + 0.5 * ln(1 + coalesce(r.inbound_citation_count, 0))) AS rank FROM (SELECT * FROM (SELECT * FROM articles r WHERE (((cardinality(lg_tokens('wetboek')) > 0 AND r.s_display_name_t @> lg_tokens('wetboek')) OR (char_length('wetboek') >= 3 AND (r.s_display_name_g LIKE lg_like(lg_fold('wetboek')) || '%' OR r.s_display_name_g LIKE '%' || chr(31) || lg_like(lg_fold('wetboek')) || '%')) OR (char_length('wetboek') BETWEEN 3 AND 12 AND r.s_display_name_g LIKE '%' || lg_like(lg_fold('wetboek')) || '%') OR (cardinality(lg_tokens('wetboek')) > 0 AND r.s_heading_t @> lg_tokens('wetboek')) OR (char_length('wetboek') >= 3 AND (r.s_heading_g LIKE lg_like(lg_fold('wetboek')) || '%' OR r.s_heading_g LIKE '%' || chr(31) || lg_like(lg_fold('wetboek')) || '%')) OR r.s_heading_n @> ARRAY[lg_fold('wetboek')] OR (char_length('wetboek') BETWEEN 3 AND 12 AND r.s_heading_g LIKE '%' || lg_like(lg_fold('wetboek')) || '%') OR (cardinality(lg_tokens('wetboek')) > 0 AND r.s_breadcrumb_title_t @> lg_tokens('wetboek')) OR (cardinality(lg_tokens('wetboek')) > 0 AND r.s_text_t @> lg_tokens('wetboek')) OR (cardinality(lg_tokens('wetboek')) > 0 AND r.s_article_number_t @> lg_tokens('wetboek')) OR (char_length('wetboek') >= 3 AND r.s_article_number_p ILIKE '%' || chr(31) || lg_like('wetboek') || '%') OR r.s_article_number_n @> ARRAY[lg_fold('wetboek')] OR (cardinality(lg_tokens('wetboek')) > 0 AND r.s_bwb_id_t @> lg_tokens('wetboek')) OR (char_length('wetboek') >= 3 AND r.s_bwb_id_p ILIKE '%' || chr(31) || lg_like('wetboek') || '%') OR r.s_bwb_id_n @> ARRAY[lg_fold('wetboek')]) AND ((cardinality(lg_tokens('strafrecht')) > 0 AND r.s_display_name_t @> lg_tokens('strafrecht')) OR (char_length('strafrecht') >= 3 AND (r.s_display_name_g LIKE lg_like(lg_fold('strafrecht')) || '%' OR r.s_display_name_g LIKE '%' || chr(31) || lg_like(lg_fold('strafrecht')) || '%')) OR (char_length('strafrecht') BETWEEN 3 AND 12 AND r.s_display_name_g LIKE '%' || lg_like(lg_fold('strafrecht')) || '%') OR (cardinality(lg_tokens('strafrecht')) > 0 AND r.s_heading_t @> lg_tokens('strafrecht')) OR (char_length('strafrecht') >= 3 AND (r.s_heading_g LIKE lg_like(lg_fold('strafrecht')) || '%' OR r.s_heading_g LIKE '%' || chr(31) || lg_like(lg_fold('strafrecht')) || '%')) OR r.s_heading_n @> ARRAY[lg_fold('strafrecht')] OR (char_length('strafrecht') BETWEEN 3 AND 12 AND r.s_heading_g LIKE '%' || lg_like(lg_fold('strafrecht')) || '%') OR (cardinality(lg_tokens('strafrecht')) > 0 AND r.s_breadcrumb_title_t @> lg_tokens('strafrecht')) OR (cardinality(lg_tokens('strafrecht')) > 0 AND r.s_text_t @> lg_tokens('strafrecht')) OR (cardinality(lg_tokens('strafrecht')) > 0 AND r.s_article_number_t @> lg_tokens('strafrecht')) OR (char_length('strafrecht') >= 3 AND r.s_article_number_p ILIKE '%' || chr(31) || lg_like('strafrecht') || '%') OR r.s_article_number_n @> ARRAY[lg_fold('strafrecht')] OR (cardinality(lg_tokens('strafrecht')) > 0 AND r.s_bwb_id_t @> lg_tokens('strafrecht')) OR (char_length('strafrecht') >= 3 AND r.s_bwb_id_p ILIKE '%' || chr(31) || lg_like('strafrecht') || '%') OR r.s_bwb_id_n @> ARRAY[lg_fold('strafrecht')])) AND r.stub IS NOT TRUE OFFSET 0) r ORDER BY r.inbound_citation_count DESC NULLS LAST, r.key LIMIT 1000) r CROSS JOIN LATERAL (SELECT coalesce(cardinality(r.s_display_name_t), 0) AS l0, cardinality(array_positions(r.s_display_name_t, 'wetboek'::text)) AS t0, lg_ngrams(char_length(r.s_display_name_g)) AS l2, (CASE WHEN char_length('wetboek') BETWEEN 3 AND 12 THEN (char_length(r.s_display_name_g) - char_length(replace(r.s_display_name_g, lg_fold('wetboek'), ''))) / char_length('wetboek') ELSE 0 END) AS t2, coalesce(cardinality(r.s_breadcrumb_title_t), 0) AS l7, cardinality(array_positions(r.s_breadcrumb_title_t, 'wetboek'::text)) AS t7, coalesce(cardinality(r.s_text_t), 0) AS l8, cardinality(array_positions(r.s_text_t, 'wetboek'::text)) AS t8, cardinality(array_positions(r.s_display_name_t, 'strafrecht'::text)) AS t15, (CASE WHEN char_length('strafrecht') BETWEEN 3 AND 12 THEN (char_length(r.s_display_name_g) - char_length(replace(r.s_display_name_g, lg_fold('strafrecht'), ''))) / char_length('strafrecht') ELSE 0 END) AS t17, coalesce(cardinality(r.s_heading_t), 0) AS l3, cardinality(array_positions(r.s_heading_t, 'strafrecht'::text)) AS t18, lg_ngrams(char_length(r.s_heading_g)) AS l6, (CASE WHEN char_length('strafrecht') BETWEEN 3 AND 12 THEN (char_length(r.s_heading_g) - char_length(replace(r.s_heading_g, lg_fold('strafrecht'), ''))) / char_length('strafrecht') ELSE 0 END) AS t21, cardinality(array_positions(r.s_breadcrumb_title_t, 'strafrecht'::text)) AS t22, cardinality(array_positions(r.s_text_t, 'strafrecht'::text)) AS t23 OFFSET 0) f ORDER BY tier DESC, rank DESC, r.key LIMIT 6 ) top JOIN articles r ON r.id = top.id LEFT JOIN LATERAL ( SELECT i.props FROM instruments i WHERE r.bwb_id IS NOT NULL AND i.bwb_id = r.bwb_id ORDER BY i.key LIMIT 1 ) by_bwb ON true LEFT JOIN LATERAL ( SELECT i.props FROM instruments i WHERE r.celex IS NOT NULL AND i.celex = r.celex ORDER BY i.key LIMIT 1 ) by_celex ON true ORDER BY top.tier DESC, top.rank DESC, r.key;

-- 3b. articles 'wetboek van strafrecht', again
EXPLAIN (ANALYZE, BUFFERS)
SELECT json_build_object( 'id', r.id, 'key', r.key, 'collection', 'articles', 'type', r.type, 'display_name', r.props -> 'display_name', 'snippet', left(coalesce(r.props ->> 'text', ''), 200), 'extra', json_build_object( 'bwb_id', r.props -> 'bwb_id', 'celex', r.props -> 'celex', 'article_number', r.props -> 'article_number', 'heading', r.props -> 'heading', 'division_titles', ( SELECT coalesce(json_agg(b -> 'title' ORDER BY n), '[]'::json) FROM json_array_elements(CASE WHEN json_typeof(r.props -> 'breadcrumb') = 'array' THEN r.props -> 'breadcrumb' ELSE '[]'::json END) WITH ORDINALITY AS c(b, n) WHERE coalesce(json_typeof(b -> 'title'), 'null') <> 'null' ), 'instrument_title', (CASE WHEN coalesce(json_typeof(coalesce(by_bwb.props, by_celex.props) -> 'citation_title'), 'null') <> 'null' THEN coalesce(by_bwb.props, by_celex.props) -> 'citation_title' WHEN coalesce(json_typeof(coalesce(by_bwb.props, by_celex.props) -> 'title'), 'null') <> 'null' THEN coalesce(by_bwb.props, by_celex.props) -> 'title' END), 'citation_title', coalesce(by_bwb.props, by_celex.props) -> 'citation_title', 'short_title', coalesce(by_bwb.props, by_celex.props) -> 'short_title', 'instrument_abbreviation', r.props -> 'instrument_abbreviation', 'expired_on', least( lg_str(coalesce(by_bwb.props, by_celex.props) -> 'date_expired'), (CASE WHEN r.bwb_id IS NULL THEN NULL WHEN r.stam_id IS NOT NULL THEN ( SELECT v.valid_until FROM article_versions v WHERE v.bwb_id = r.bwb_id AND v.stam_id = r.stam_id ORDER BY v.valid_from DESC NULLS LAST, v.key DESC LIMIT 1 ) ELSE ( SELECT v.valid_until FROM article_versions v WHERE v.bwb_id = r.bwb_id AND v.article_number = r.article_number ORDER BY v.valid_from DESC NULLS LAST, v.key DESC LIMIT 1 ) END) ) ) ) FROM ( SELECT r.id, (CASE WHEN (r.s_display_name_g LIKE lg_like(lg_fold('wetboek strafrecht')) || '%' OR r.s_display_name_g LIKE '%' || chr(31) || lg_like(lg_fold('wetboek strafrecht')) || '%') OR (r.s_heading_g LIKE lg_like(lg_fold('wetboek strafrecht')) || '%' OR r.s_heading_g LIKE '%' || chr(31) || lg_like(lg_fold('wetboek strafrecht')) || '%') THEN 2 WHEN (f.t7 > 0) AND (f.t18 > 0 OR f.t22 > 0) THEN 1 ELSE 0 END) AS tier, ((CASE WHEN f.t0 > 0 THEN 2.0954469782626255 * f.t0 / (f.t0 + 0.3 + 0.15064675338972164 * f.l0) ELSE 0 END + CASE WHEN f.t2 > 0 THEN 2.09544700392961 * f.t2 / (f.t2 + 0.3 + 0.003080516176958878 * f.l2) ELSE 0 END + CASE WHEN f.t7 > 0 THEN 18.011473079960783 * f.t7 / (f.t7 + 0.3 + 0.09741189844638119 * f.l7) ELSE 0 END + CASE WHEN f.t8 > 0 THEN 8.534757105030126 * f.t8 / (f.t8 + 0.3 + 0.005653691726213725 * f.l8) ELSE 0 END + CASE WHEN f.t15 > 0 THEN 10.624706318033402 * f.t15 / (f.t15 + 0.3 + 0.15064675338972164 * f.l0) ELSE 0 END + CASE WHEN f.t17 > 0 THEN 10.624706614216857 * f.t17 / (f.t17 + 0.3 + 0.003080516176958878 * f.l2) ELSE 0 END + CASE WHEN f.t18 > 0 THEN 67.14616047648563 * f.t18 / (f.t18 + 0.3 + 0.1943145869947276 * f.l3) ELSE 0 END + CASE WHEN f.t21 > 0 THEN 67.14616030122873 * f.t21 / (f.t21 + 0.3 + 0.0027465505099246194 * f.l6) ELSE 0 END + CASE WHEN f.t22 > 0 THEN 26.00914772628777 * f.t22 / (f.t22 + 0.3 + 0.09741189844638119 * f.l7) ELSE 0 END + CASE WHEN f.t23 > 0 THEN 11.033628563627548 * f.t23 / (f.t23 + 0.3 + 0.005653691726213725 * f.l8) ELSE 0 END) + 0.5 * ln(1 + coalesce(r.inbound_citation_count, 0))) AS rank FROM (SELECT * FROM (SELECT * FROM articles r WHERE (((cardinality(lg_tokens('wetboek')) > 0 AND r.s_display_name_t @> lg_tokens('wetboek')) OR (char_length('wetboek') >= 3 AND (r.s_display_name_g LIKE lg_like(lg_fold('wetboek')) || '%' OR r.s_display_name_g LIKE '%' || chr(31) || lg_like(lg_fold('wetboek')) || '%')) OR (char_length('wetboek') BETWEEN 3 AND 12 AND r.s_display_name_g LIKE '%' || lg_like(lg_fold('wetboek')) || '%') OR (cardinality(lg_tokens('wetboek')) > 0 AND r.s_heading_t @> lg_tokens('wetboek')) OR (char_length('wetboek') >= 3 AND (r.s_heading_g LIKE lg_like(lg_fold('wetboek')) || '%' OR r.s_heading_g LIKE '%' || chr(31) || lg_like(lg_fold('wetboek')) || '%')) OR r.s_heading_n @> ARRAY[lg_fold('wetboek')] OR (char_length('wetboek') BETWEEN 3 AND 12 AND r.s_heading_g LIKE '%' || lg_like(lg_fold('wetboek')) || '%') OR (cardinality(lg_tokens('wetboek')) > 0 AND r.s_breadcrumb_title_t @> lg_tokens('wetboek')) OR (cardinality(lg_tokens('wetboek')) > 0 AND r.s_text_t @> lg_tokens('wetboek')) OR (cardinality(lg_tokens('wetboek')) > 0 AND r.s_article_number_t @> lg_tokens('wetboek')) OR (char_length('wetboek') >= 3 AND r.s_article_number_p ILIKE '%' || chr(31) || lg_like('wetboek') || '%') OR r.s_article_number_n @> ARRAY[lg_fold('wetboek')] OR (cardinality(lg_tokens('wetboek')) > 0 AND r.s_bwb_id_t @> lg_tokens('wetboek')) OR (char_length('wetboek') >= 3 AND r.s_bwb_id_p ILIKE '%' || chr(31) || lg_like('wetboek') || '%') OR r.s_bwb_id_n @> ARRAY[lg_fold('wetboek')]) AND ((cardinality(lg_tokens('strafrecht')) > 0 AND r.s_display_name_t @> lg_tokens('strafrecht')) OR (char_length('strafrecht') >= 3 AND (r.s_display_name_g LIKE lg_like(lg_fold('strafrecht')) || '%' OR r.s_display_name_g LIKE '%' || chr(31) || lg_like(lg_fold('strafrecht')) || '%')) OR (char_length('strafrecht') BETWEEN 3 AND 12 AND r.s_display_name_g LIKE '%' || lg_like(lg_fold('strafrecht')) || '%') OR (cardinality(lg_tokens('strafrecht')) > 0 AND r.s_heading_t @> lg_tokens('strafrecht')) OR (char_length('strafrecht') >= 3 AND (r.s_heading_g LIKE lg_like(lg_fold('strafrecht')) || '%' OR r.s_heading_g LIKE '%' || chr(31) || lg_like(lg_fold('strafrecht')) || '%')) OR r.s_heading_n @> ARRAY[lg_fold('strafrecht')] OR (char_length('strafrecht') BETWEEN 3 AND 12 AND r.s_heading_g LIKE '%' || lg_like(lg_fold('strafrecht')) || '%') OR (cardinality(lg_tokens('strafrecht')) > 0 AND r.s_breadcrumb_title_t @> lg_tokens('strafrecht')) OR (cardinality(lg_tokens('strafrecht')) > 0 AND r.s_text_t @> lg_tokens('strafrecht')) OR (cardinality(lg_tokens('strafrecht')) > 0 AND r.s_article_number_t @> lg_tokens('strafrecht')) OR (char_length('strafrecht') >= 3 AND r.s_article_nu