-- 5b. judgments 'wetboek van strafrecht', again
EXPLAIN (ANALYZE, BUFFERS)
SELECT json_build_object( 'id', r.id, 'key', r.key, 'collection', 'judgments', 'type', r.type, 'display_name', r.props -> 'display_name', 'snippet', left(coalesce(r.props ->> 'summary', ''), 200), 'extra', json_build_object( 'ecli', r.props -> 'ecli', 'appno', r.props -> 'appno', 'names', r.props -> 'names' ), 'cite_props', json_build_object( 'date', r.props -> 'date', 'date_eff', to_json(r.date_eff), 'court', r.props -> 'court', 'advocate_general', r.props -> 'advocate_general', 'advocate_general_role', r.props -> 'advocate_general_role', 'case_number', r.props -> 'case_number' ) ) FROM ( SELECT r.id, 0 AS tier, (CASE WHEN f.t7 > 0 THEN 13.36864451284279 * f.t7 / (f.t7 + 0.3 + 0.009956080969520853 * f.l7) ELSE 0 END + CASE WHEN f.t19 > 0 THEN 11.563570969168232 * f.t19 / (f.t19 + 0.3 + 0.009956080969520853 * f.l7) ELSE 0 END) AS rank FROM (SELECT * FROM (SELECT * FROM judgments r WHERE ((cardinality(lg_tokens('wetboek')) > 0 AND r.s_display_name_t @> lg_tokens('wetboek')) OR (char_length('wetboek') >= 3 AND (r.s_display_name_g LIKE lg_like(lg_fold('wetboek')) || '%' OR r.s_display_name_g LIKE '%' || chr(31) || lg_like(lg_fold('wetboek')) || '%')) OR (char_length('wetboek') BETWEEN 3 AND 12 AND r.s_display_name_g LIKE '%' || lg_like(lg_fold('wetboek')) || '%') OR (cardinality(lg_tokens('wetboek')) > 0 AND r.s_names_t @> lg_tokens('wetboek')) OR (char_length('wetboek') >= 3 AND (r.s_names_g LIKE lg_like(lg_fold('wetboek')) || '%' OR r.s_names_g LIKE '%' || chr(31) || lg_like(lg_fold('wetboek')) || '%')) OR r.s_names_n @> ARRAY[lg_fold('wetboek')] OR (char_length('wetboek') BETWEEN 3 AND 12 AND r.s_names_g LIKE '%' || lg_like(lg_fold('wetboek')) || '%') OR (cardinality(lg_tokens('wetboek')) > 0 AND r.s_summary_t @> lg_tokens('wetboek')) OR (char_length('wetboek') >= 3 AND r.s_ecli_p ILIKE '%' || chr(31) || lg_like('wetboek') || '%') OR r.s_ecli_n @> ARRAY[lg_fold('wetboek')] OR (char_length('wetboek') >= 3 AND r.s_appno_p ILIKE '%' || chr(31) || lg_like('wetboek') || '%') OR r.s_appno_n @> ARRAY[lg_fold('wetboek')]) AND ((cardinality(lg_tokens('strafrecht')) > 0 AND r.s_display_name_t @> lg_tokens('strafrecht')) OR (char_length('strafrecht') >= 3 AND (r.s_display_name_g LIKE lg_like(lg_fold('strafrecht')) || '%' OR r.s_display_name_g LIKE '%' || chr(31) || lg_like(lg_fold('strafrecht')) || '%')) OR (char_length('strafrecht') BETWEEN 3 AND 12 AND r.s_display_name_g LIKE '%' || lg_like(lg_fold('strafrecht')) || '%') OR (cardinality(lg_tokens('strafrecht')) > 0 AND r.s_names_t @> lg_tokens('strafrecht')) OR (char_length('strafrecht') >= 3 AND (r.s_names_g LIKE lg_like(lg_fold('strafrecht')) || '%' OR r.s_names_g LIKE '%' || chr(31) || lg_like(lg_fold('strafrecht')) || '%')) OR r.s_names_n @> ARRAY[lg_fold('strafrecht')] OR (char_length('strafrecht') BETWEEN 3 AND 12 AND r.s_names_g LIKE '%' || lg_like(lg_fold('strafrecht')) || '%') OR (cardinality(lg_tokens('strafrecht')) > 0 AND r.s_summary_t @> lg_tokens('strafrecht')) OR (char_length('strafrecht') >= 3 AND r.s_ecli_p ILIKE '%' || chr(31) || lg_like('strafrecht') || '%') OR r.s_ecli_n @> ARRAY[lg_fold('strafrecht')] OR (char_length('strafrecht') >= 3 AND r.s_appno_p ILIKE '%' || chr(31) || lg_like('strafrecht') || '%') OR r.s_appno_n @> ARRAY[lg_fold('strafrecht')]) OFFSET 0) r ORDER BY r.inbound_citation_count DESC NULLS LAST, r.date_eff DESC NULLS LAST, r.key LIMIT 1000) r CROSS JOIN LATERAL (SELECT coalesce(cardinality(r.s_summary_t), 0) AS l7, cardinality(array_positions(r.s_summary_t, 'wetboek'::text)) AS t7, cardinality(array_positions(r.s_summary_t, 'strafrecht'::text)) AS t19 OFFSET 0) f ORDER BY tier DESC, rank DESC, r.key LIMIT 6 ) top JOIN judgments r ON r.id = top.id ORDER BY top.tier DESC, top.rank DESC, r.key;
